import * as React from "react"
import { useMemo } from "react"
import type { FrameBlockProps } from "../../index"
import ImageWithOptions from "../image/image-with-options"
import type { ImageOption } from "../image/image-with-options"
import ImageBleedWithOverlay from "../image/image-bleed-with-overlay"
import ImageSpreadWithOverlay from "../image/image-spread-with-overlay"
import { renderOverlay } from "../image/image-overlay-utils"
import { imageUrl } from "../image/image-url.js"
import { frameDisplay, frameOverlays } from "./frame-helpers"
import type { FrameOptions } from "./frame-helpers"
import { frameDeclaration, getFrameDialogProps } from "./frame-dialog.js"

type FrameBlockMode = "bleed" | "spread" | "auto"

/**
 * What goes over the shown image: the overlays, bottom to top, each fitted to the frame as
 * ImageBlock fits `annotationSvg` (inline SVG at 100% × 100%, `xMidYMid slice`), then the
 * template's children. One component rather than markup: ImageWithOptions clones its element
 * children with a `dataUhuu` prop, which a DOM element would render as an attribute.
 */
const FrameContent = ({ svgs, className, children }: { svgs: string[]; className?: string; children?: React.ReactNode }) => (
  <>
    {svgs.map((svg, index) => (
      <React.Fragment key={index}>{renderOverlay(svg, className)}</React.Fragment>
    ))}
    {children}
  </>
)

/**
 * An image slot that several dialogs write (a map, a satellite view, a cadastral plan, a gallery
 * pick, a crop, an annotation), saved as one `uhuu.frame.v1` value. The template declares the slot;
 * the editor owns the value.
 *
 *   <FrameBlock
 *     path="location.image"
 *     value={location.image}
 *     sources={[{ type: 'map', title: 'Create Map', config: mapConfig }, { type: 'image', title: 'Choose Image' }]}
 *     layers={[{ type: 'annotation', title: 'Annotate' }]}
 *     className="absolute left-[18mm] top-[207mm] h-[155mm] w-[314mm]"
 *   />
 *
 * - Shows the frame's image through `imageUrl()` (print-aware) and the active source's overlays
 *   over it (its layers, then `overlaySvg`). Cadastral's own outline is part of its image; set
 *   `intrinsicOverlays` for a source whose image does not have its outline baked in.
 * - Values saved before frames render through the same helpers: `legacyPrecedence` picks the image
 *   an old map-plus-pick value shows, `annotation` is the overlay saved at `annotationPath`.
 * - In the editor a click opens `$uhuu.editFrame`; an older SDK gets `editDialog` with the legacy
 *   `types`. Renderer mode has no click handler (getDialogProps' guard).
 * - Layout props (`mode`, bleed geometry, `placeholder`, `options`, `renderImage`, …) are
 *   ImageBlock's, with ImageBlock's mode rule. ImageBlock stays the component for a slot one dialog
 *   writes.
 *
 * See docs/frame-block.md.
 */
const FrameBlock = (props: FrameBlockProps) => {
  const {
    path,
    sources,
    layers,
    transforms,
    ratio,
    legacyPrecedence,
    legacyDataImage,
    intrinsicOverlays,
    annotationPath,
    value,
    annotation,
    src: srcOverride,
    imageUrlOptions,
    mode: modeProp,
    side,
    alt,
    className,
    imageClassName,
    style,
    imageStyle,
    backgroundColor,
    width,
    height,
    left,
    right,
    top,
    bottom,
    pageWidth,
    pageHeight,
    bleed,
    overlaySvg,
    overlayClassName,
    options,
    dialogProps,
    placeholder,
    children,
    imageProps,
    renderImage,
    onError,
  } = props

  // Templates pass `sources` inline, so the memo below keys on the source types, not the array.
  const sourceKey = (Array.isArray(sources) ? sources : [])
    .map((source) => source?.type)
    .filter((type): type is string => typeof type === "string" && type !== "")
    .join("\n")

  const { src, svgs, shownUrl } = useMemo(() => {
    const frameOptions: FrameOptions = {
      sources: sourceKey ? sourceKey.split("\n") : undefined,
      legacyPrecedence,
      legacyDataImage,
      intrinsicOverlays,
      legacyLayer: annotation ?? undefined,
    }
    // The shown image's own mimeType keeps imageUrl's SVG pass-through when its URL has no `.svg`.
    const shown = frameDisplay(value, frameOptions)
    const overlays = frameOverlays(value, frameOptions).map((overlay) => overlay.svg)
    return {
      src: srcOverride ?? imageUrl(shown.url ? { contentUrl: shown.url, mimeType: shown.mimeType } : null, imageUrlOptions),
      svgs: overlaySvg ? [...overlays, overlaySvg] : overlays,
      shownUrl: shown.url,
    }
  }, [value, sourceKey, legacyPrecedence, legacyDataImage, intrinsicOverlays, annotation, srcOverride, imageUrlOptions, overlaySvg])

  const binding = useMemo(
    () => getFrameDialogProps(
      frameDeclaration({ path, sources, layers, transforms, ratio, legacyPrecedence, legacyDataImage, annotationPath }),
      // An editor without frames offers the annotation on the image shown now.
      { image: shownUrl, annotation },
    ),
    [path, sources, layers, transforms, ratio, legacyPrecedence, legacyDataImage, annotationPath, shownUrl, annotation],
  )

  // ImageBlock's rule: an explicit mode wins, then `side` selects spread, bleed geometry bleed.
  const hasBleedDimensions = [width, height, left, right, top, bottom].some((entry) => entry !== undefined)
  const mode: FrameBlockMode = modeProp ?? (side !== undefined ? "spread" : hasBleedDimensions ? "bleed" : "auto")

  // Inside the bound image element in every mode, so overlays cover exactly the image.
  const content = <FrameContent svgs={svgs} className={overlayClassName}>{children}</FrameContent>
  const imageOptions = options as ImageOption[] | undefined

  if (mode === "auto") {
    return (
      <ImageWithOptions
        src={src}
        alt={alt}
        className={className}
        style={style}
        imageClassName={imageClassName}
        imageStyle={imageStyle}
        options={imageOptions}
        binding={binding}
        dialogProps={dialogProps}
        placeholder={placeholder}
        imageProps={imageProps}
        renderImage={renderImage}
        onError={onError}
      >
        {content}
      </ImageWithOptions>
    )
  }

  const layoutProps = {
    src,
    backgroundColor,
    width,
    height,
    left,
    right,
    top,
    bottom,
    pageWidth,
    pageHeight,
    bleed,
    imageClassName,
    onError,
    binding,
  }

  if (mode === "spread") {
    return (
      <ImageSpreadWithOverlay
        className={className}
        style={style}
        options={imageOptions}
        spreadProps={{ ...layoutProps, side }}
      >
        {content}
      </ImageSpreadWithOverlay>
    )
  }

  return (
    <ImageBleedWithOverlay
      className={className}
      style={style}
      options={imageOptions}
      bleedProps={layoutProps}
    >
      {content}
    </ImageBleedWithOverlay>
  )
}

export default FrameBlock
