// Hold pagination pending while intrinsic image sizes or web fonts can still change the flow.
// ResizeObserver alone is insufficient: it may not deliver callbacks in a background document.
//
// `root` is the page's hidden measurement copy, which the library owns: images there load eagerly.
// A `loading="lazy"` image (CMS HTML, next/image) never intersects the viewport offscreen, so it
// would never load and pagination would wait forever. The visible sheets keep their attribute.
//
// A resource that never finishes (a hung request) holds pagination for at most `waitMs`: then the
// document measures with what it has, a warning names the resource, and its listeners stay, so a
// late arrival still triggers a remeasure.
import { warnImageFailed, warnOnce } from '../utility/warn-once.js';

export const ASSET_WAIT_MS = 10000;

export function observeFlowAssets(root, { begin, onReady, doc = root.ownerDocument, waitMs = ASSET_WAIT_MS }) {
  const images = new Map();
  const fonts = doc?.fonts;
  let stopped = false;
  let finishFonts = null;

  const hold = (label) => {
    const finish = begin();
    const timer = setTimeout(() => {
      finish();
      // Every measuring FlowArea holds the same font or image: one warning names it.
      warnOnce(
        `asset-wait:${label}`,
        `[uhuu-components] ${label} is still loading after ${Math.round(waitMs / 1000)} s; pagination ` +
        'stops waiting for it and measures again if it arrives.'
      );
    }, waitMs);
    return () => {
      clearTimeout(timer);
      finish();
    };
  };

  const watchFonts = () => {
    if (stopped || !fonts || fonts.status !== 'loading' || finishFonts) return;
    const loading = [...new Set(Array.from(fonts).filter((face) => face.status === 'loading').map((face) => face.family))];
    finishFonts = hold(loading.length ? `Web font ${loading.join(', ')}` : 'A web font');
    const ready = () => {
      if (stopped) return;
      onReady();
      finishFonts?.();
      finishFonts = null;
    };
    fonts.ready.then(ready, ready);
  };
  fonts?.addEventListener('loading', watchFonts);
  watchFonts();

  const sync = () => {
    for (const [image, cleanup] of images) {
      if (!root.contains(image) || image.complete) cleanup();
    }
    for (const image of root.querySelectorAll('img')) {
      if (image.loading === 'lazy') image.loading = 'eager';
      if (image.complete || images.has(image)) continue;
      const finish = hold(`Image ${image.currentSrc || image.src || '(no src)'}`);
      const cleanup = () => {
        image.removeEventListener('load', loaded);
        image.removeEventListener('error', loaded);
        images.delete(image);
        finish();
      };
      const loaded = () => {
        if (!stopped) onReady();
        cleanup();
      };
      images.set(image, cleanup);
      image.addEventListener('load', loaded);
      // A failed image is settled too (it prints empty), and says which it is.
      image.addEventListener('error', () => warnImageFailed(image.currentSrc || image.src), { once: true });
      image.addEventListener('error', loaded);
    }
    // Catch a font load that started before its `loading` event is delivered.
    watchFonts();
  };
  sync();
  return {
    sync,
    disconnect() {
      stopped = true;
      fonts?.removeEventListener('loading', watchFonts);
      finishFonts?.();
      finishFonts = null;
      for (const cleanup of images.values()) cleanup();
    },
  };
}
