import React, { createContext } from 'react';

/** What Pagination provides (PageSizeUtils.pageParams): page geometry in mm plus print options. */
export interface UhuuPageConfig {
  width?: number;
  height?: number;
  bleed?: number;
  showBleed?: boolean;
  preview?: string;
  [option: string]: any;
}

export interface UhuuConfig {
  page?: UhuuPageConfig;
  [option: string]: any;
}

// Create the Context
export const ConfigContext = createContext<UhuuConfig | null>(null);

// ConfigProvider Component
const ConfigProvider = ({ config, children }: { config: UhuuConfig | null; children?: React.ReactNode }) => {
  return (
    <ConfigContext.Provider value={config}>
      {children}
    </ConfigContext.Provider>
  );
};

export default ConfigProvider;
