import { createContext, createElement, useCallback, useContext, useRef, useState, useSyncExternalStore, type ReactNode } from 'react';

/** Each InteractiveModeProvider owns its toolbar slots; provider-less controls share a fallback. */
function createToolbarSlots() {
  const slots: HTMLElement[] = [];
  const listeners = new Set<() => void>();
  return {
    getSnapshot: () => slots.at(-1) ?? null,
    subscribe(listener: () => void) {
      listeners.add(listener);
      return () => { listeners.delete(listener); };
    },
    replace(previous: HTMLElement | null, element: HTMLElement | null) {
      if (previous) {
        const index = slots.lastIndexOf(previous);
        if (index !== -1) slots.splice(index, 1);
      }
      if (element) slots.push(element);
      listeners.forEach((listener) => listener());
    },
  };
}

const fallbackSlots = createToolbarSlots();
const ToolbarSlotsContext = createContext(fallbackSlots);
const getServerSlot = () => null;

export function ToolbarSlotProvider({ children }: { children: ReactNode }) {
  const [store] = useState(createToolbarSlots);
  return createElement(ToolbarSlotsContext.Provider, { value: store }, children);
}

/** The provider-less toolbar, used when creating a provider-less floating bar after mount. */
export function getToolbarSlot(): HTMLElement | null {
  return fallbackSlots.getSnapshot();
}

/** The nearest provider's toolbar, or the provider-less fallback. */
export function useToolbarSlot(): HTMLElement | null {
  const store = useContext(ToolbarSlotsContext);
  return useSyncExternalStore(store.subscribe, store.getSnapshot, getServerSlot);
}

/** React 18 calls the ref with null on unmount, so track the registered element explicitly. */
export function useToolbarSlotRef(): (element: HTMLElement | null) => void {
  const store = useContext(ToolbarSlotsContext);
  const registered = useRef<HTMLElement | null>(null);
  return useCallback((element: HTMLElement | null) => {
    const previous = registered.current;
    if (previous === element) return;
    registered.current = element;
    store.replace(previous, element);
  }, [store]);
}
