// Document contract for PDF consumers: `<html data-uhuu-pagination="measuring|settled|error">`.
// A quiet timer is only a debounce: successful measurement AND a matching committed React tree are
// required before a scope can settle. Every page root publishes: a PageEditor scope tracks its
// flow pages, a standalone Static.Pagination publishes a scope with none, so a renderer can tell
// a document that implements the contract (attribute present) from one that predates it.
import { announceTemplateRuntime } from '../runtime/template-runtime.js';

export const PAGINATION_ATTRIBUTE = 'data-uhuu-pagination';
export const SETTLE_MS = 50;

// What a commit decides: the flow pages and the plan signatures they render. Owners and object
// identities are left out, so a re-render with the same plans does not restart the debounce.
function commitSignature(pageKeys, layouts) {
  const plans = Object.keys(layouts ?? {}).sort().map((pageKey) => {
    const signatures = layouts[pageKey]?.signatures ?? {};
    return `${pageKey}=${Object.keys(signatures).sort().map((flowId) => `${flowId}:${signatures[flowId]}`).join(',')}`;
  });
  return `${pageKeys.join('|')}#${plans.join(';')}`;
}

export function createPaginationReadiness({ doc, settleMs = SETTLE_MS, onFirstScope } = {}) {
  const scopes = new Map();
  // Document-wide inputs the library is still loading (a brand kit and its font stylesheets).
  const holds = new Set();

  const publish = () => {
    const root = (doc ?? (typeof document === 'undefined' ? undefined : document))?.documentElement;
    if (!root) return;
    const states = [...scopes.values()].map((scope) => scope.state);
    if (!states.length) {
      root.removeAttribute(PAGINATION_ATTRIBUTE);
      return;
    }
    const state = holds.size || states.includes('measuring')
      ? 'measuring'
      : states.includes('error') ? 'error' : 'settled';
    if (root.getAttribute(PAGINATION_ATTRIBUTE) !== state) root.setAttribute(PAGINATION_ATTRIBUTE, state);
  };

  return {
    /**
     * Holds every scope at `measuring` until the returned release runs. A release remeasures every
     * flow area, so a layout the held input changed (fonts, CSS variables) is planned again even
     * in a background document, where ResizeObserver may not report it. With `waitMs` the hold
     * releases itself after that long and a console warning names `label`: an input that never
     * finishes cannot keep a document from printing.
     */
    hold({ label = 'A pagination hold', waitMs } = {}) {
      const token = Symbol();
      holds.add(token);
      publish();
      let timer = null;
      const release = () => {
        clearTimeout(timer);
        if (!holds.delete(token)) return;
        for (const scope of scopes.values()) scope.refresh();
        publish();
      };
      if (Number.isFinite(waitMs)) {
        timer = setTimeout(() => {
          console.warn(
            `[uhuu-components] ${label} has held pagination for ${Math.round(waitMs / 1000)} s; ` +
            'the document stops waiting for it.'
          );
          release();
        }, waitMs);
      }
      return release;
    },

    createScope() {
      if (!scopes.size && onFirstScope) onFirstScope();
      const identity = Symbol();
      const areas = new Set();
      let committed = null;
      let timer = null;
      let mounted = false;
      const entry = {
        state: 'measuring',
        refresh: () => {
          for (const area of areas) area.remeasure?.();
          update();
        },
      };

      const setState = (state) => {
        if (!mounted) return;
        entry.state = state;
        scopes.set(identity, entry);
        publish();
      };
      // An area matches the commit when React rendered exactly the plan it measured.
      const matchesCommit = (area) => Boolean(area.measurement) &&
        committed.layouts[area.pageKey]?.signatures?.[area.measurement.flowId] === area.measurement.signature;
      const update = () => {
        clearTimeout(timer);
        timer = null;
        if (!mounted) return;
        const active = [...areas].filter((area) => committed?.pageKeys.has(area.pageKey));
        const covered = new Set(active.map((area) => area.pageKey));
        const pending = !committed ||
          active.some((area) => area.jobs.size > 0) ||
          [...committed.pageKeys].some((pageKey) => !covered.has(pageKey)) ||
          active.some((area) => !area.failure && !matchesCommit(area));
        setState('measuring');
        if (pending) return;
        timer = setTimeout(() => {
          timer = null;
          // An item taller than its region is not a failure: it prints scaled to fit (flow-static).
          setState(active.some((area) => area.failure) ? 'error' : 'settled');
        }, settleMs);
      };

      return {
        // Layout cleanup runs when Suspense hides the tree too. It invalidates completion,
        // whereas the passive effect owns disposal when the editor actually unmounts.
        commit(pageKeys, layouts) {
          const keys = [...pageKeys];
          const signature = commitSignature(keys, layouts);
          if (mounted && committed?.signature === signature) return;
          committed = { pageKeys: new Set(keys), layouts, signature };
          mounted = true;
          update();
        },
        suspend() {
          committed = null;
          update();
        },
        unmount() {
          mounted = false;
          committed = null;
          clearTimeout(timer);
          timer = null;
          scopes.delete(identity);
          publish();
        },
        /** `remeasure` schedules the area's measurement when a document-wide input changes. */
        registerArea(pageKey, { remeasure } = {}) {
          const area = { pageKey, remeasure, jobs: new Set(), measurement: null, failure: null };
          areas.add(area);
          update();
          return {
            begin() {
              const job = Symbol();
              area.jobs.add(job);
              update();
              return () => {
                if (!area.jobs.delete(job)) return;
                update();
              };
            },
            // An unchanged result changes nothing: a page that keeps remeasuring the same plan
            // (a ticking header) must not restart the debounce forever.
            measured(measurement, failure = null) {
              const unchanged = area.failure === failure &&
                area.measurement?.flowId === measurement?.flowId &&
                area.measurement?.signature === measurement?.signature;
              area.measurement = measurement;
              area.failure = failure;
              if (!unchanged) update();
            },
            fail(error) {
              if (area.failure === error) return;
              area.failure = error;
              update();
            },
            clear() {
              if (!area.measurement && !area.failure) return;
              area.measurement = null;
              area.failure = null;
              update();
            },
            dispose() {
              areas.delete(area);
              update();
            },
          };
        },
      };
    },
  };
}

// The first document root also tells the host which uhuu-components it runs (developer tools).
export const paginationReadiness = createPaginationReadiness({ onFirstScope: () => announceTemplateRuntime() });
